args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT ?p ?o WHERE { 
  <http://dbpedia.org/resource/Thomas_Stafford,_3rd_Earl_of_Stafford> ?p ?o .
  FILTER(?p IN (dbo:father, dbp:father, dbo:parent, dbp:parent, dbp:parents, dbo:parents))
}

PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?father ?fatherLabel WHERE {
  ?father dbp:issue <http://dbpedia.org/resource/Thomas_Stafford,_3rd_Earl_of_Stafford> .
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = "en") }
}

